  const slideshowMediaLabelRequestKey = [
    slideshowMediaLabelIds.join(','),
    state?.activeScene?.id ?? '',
    state?.activeScene?.metadata ?? '',
    state?.stagedScene?.id ?? '',
    state?.stagedScene?.metadata ?? ''
  ].join('|');

  const resolveSlideshowImages = useCallback(
